function validate([words, left, right]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  for (const w of words) {
    if (typeof w !== 'string' || w.length < 1 || w.length > 10) return 'Each word has 1 to 10 letters.';
    if (!/^[a-z]+$/.test(w)) return 'Words use only lowercase English letters.';
  }
  if (!Number.isInteger(left) || !Number.isInteger(right)) return 'left and right are integers.';
  if (left < 0 || left > right || right >= words.length) return 'Need 0 <= left <= right < words.length.';
  return null;
}

