function vowelStrings(words, left, right) {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  let count = 0;
  for (let i = left; i <= right; i++) {
    const word = words[i];
    const first = word[0];
    const last = word[word.length - 1];
    if (vowels.has(first) && vowels.has(last)) {
      count++;
    }
  }
  return count;
}

brute:
function vowelStrings(words, left, right) {
  const pattern = /^[aeiou]$|^[aeiou][a-z]*[aeiou]$/;
  return words.filter((w, idx) => idx >= left && idx <= right && pattern.test(w)).length;
}

