function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const full = 'abcdefghijklmnopqrstuvwxyz';
  const mixed = 'aeiouxyzbm';
  const n = size === 'large' ? 1000 : pick(1, 8);
  const maxLen = size === 'large' ? 10 : pick(1, 4);
  const words = [];
  for (let i = 0; i < n; i++) {
    const letters = rand() < 0.6 ? mixed : full;
    const len = pick(1, maxLen);
    let w = '';
    for (let j = 0; j < len; j++) w += letters[Math.floor(rand() * letters.length)];
    words.push(w);
  }
  let left = pick(0, n - 1);
  let right = pick(0, n - 1);
  if (left > right) [left, right] = [right, left];
  if (size === 'large' && rand() < 0.5) {
    left = pick(0, 5);
    right = n - 1 - pick(0, 5);
  }
  return [words, left, right];
}
